def calc(expr: str) -> int | str:
    class _CalcError(Exception):
        pass

    n = len(expr)
    pos = 0

    def skip_spaces() -> None:
        nonlocal pos
        while pos < n and expr[pos] == " ":
            pos += 1

    def parse_atom() -> int:
        nonlocal pos
        skip_spaces()
        if expr[pos] == "(":
            pos += 1
            val = parse_add()
            skip_spaces()
            pos += 1  # ')'
            return val
        start = pos
        while pos < n and "0" <= expr[pos] <= "9":
            pos += 1
        return int(expr[start:pos])

    def parse_power() -> int:
        nonlocal pos
        bases = [parse_atom()]
        signs = []
        while True:
            skip_spaces()
            if pos < n and expr[pos] == "^":
                pos += 1
                neg = False
                while True:
                    skip_spaces()
                    if pos < n and expr[pos] == "-":
                        neg = not neg
                        pos += 1
                    else:
                        break
                signs.append(neg)
                bases.append(parse_atom())
            else:
                break

        res = bases[-1]
        for i in range(len(signs) - 1, -1, -1):
            exp = -res if signs[i] else res
            if exp < 0:
                raise _CalcError
            res = bases[i] ** exp
        return res

    def parse_unary() -> int:
        nonlocal pos
        neg = False
        while True:
            skip_spaces()
            if pos < n and expr[pos] == "-":
                neg = not neg
                pos += 1
            else:
                break
        val = parse_power()
        return -val if neg else val

    def parse_mul() -> int:
        nonlocal pos
        val = parse_unary()
        while True:
            skip_spaces()
            if pos < n and expr[pos] in ("*", "/", "%"):
                op = expr[pos]
                pos += 1
                rhs = parse_unary()
                if op == "*":
                    val *= rhs
                else:
                    if rhs == 0:
                        raise _CalcError
                    q = abs(val) // abs(rhs)
                    if (val < 0) ^ (rhs < 0):
                        q = -q
                    if op == "/":
                        val = q
                    else:
                        val = val - rhs * q
            else:
                break
        return val

    def parse_add() -> int:
        nonlocal pos
        val = parse_mul()
        while True:
            skip_spaces()
            if pos < n and expr[pos] in ("+", "-"):
                op = expr[pos]
                pos += 1
                rhs = parse_mul()
                if op == "+":
                    val += rhs
                else:
                    val -= rhs
            else:
                break
        return val

    try:
        return parse_add()
    except _CalcError:
        return "error"
